mapper.select:
SELECT *
FROM ai_agent_prompt_memory_stream
WHERE session_id = #{key.sessionId}
  AND memory_scope = #{key.scope}
  AND prompt_contract_id = #{key.promptContractId}
  AND tool_contract_id = #{key.toolContractId}
  AND deleted = 0
LIMIT 1

mapper.update:
UPDATE ai_agent_prompt_memory_stream
SET active_request_id = #{requestId},
    lease_expire_at = #{leaseExpireAt},
    version = version + 1,
    update_time = NOW()
WHERE session_id = #{key.sessionId}
  AND memory_scope = #{key.scope}
  AND prompt_contract_id = #{key.promptContractId}
  AND tool_contract_id = #{key.toolContractId}
  AND deleted = 0
  AND (active_request_id IS NULL OR active_request_id = #{requestId}
       OR lease_expire_at IS NULL OR lease_expire_at <= #{now})

UPDATE ai_agent_prompt_memory_stream
SET latest_turn_seq = #{nextTurnSeq},
    active_request_id = NULL,
    lease_expire_at = NULL,
    version = version + 1,
    update_time = NOW()
WHERE id = #{streamId}
  AND active_request_id = #{requestId}
  AND latest_turn_seq = #{expectedLatestTurnSeq}
  AND deleted = 0
